import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
});

import { Route, Routes, useLocation } from 'react-router-dom';
import { AnimatePresence, motion } from 'framer-motion';
import Navbar from './components/Navbar.jsx';
import ParticleField from './components/ParticleField.jsx';
import CursorGlow from './components/CursorGlow.jsx';
import Home from './pages/Home.jsx';
import About from './pages/About.jsx';
import Projects from './pages/Projects.jsx';
import Research from './pages/Research.jsx';
import Contact from './pages/Contact.jsx';

const pageMotion = {
  initial: { opacity: 0, y: 18 },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: -12 },
  transition: { duration: 0.35, ease: 'easeOut' },
};

function AnimatedRoutes() {
  const location = useLocation();

  return (
    <AnimatePresence mode="wait">
      <Routes location={location} key={location.pathname}>
        <Route
          path="/"
          element={<motion.main {...pageMotion}><Home /></motion.main>}
        />
        <Route
          path="/about"
          element={<motion.main {...pageMotion}><About /></motion.main>}
        />
        <Route
          path="/projects"
          element={<motion.main {...pageMotion}><Projects /></motion.main>}
        />
        <Route
          path="/research"
          element={<motion.main {...pageMotion}><Research /></motion.main>}
        />
        <Route
          path="/contact"
          element={<motion.main {...pageMotion}><Contact /></motion.main>}
        />
      </Routes>
    </AnimatePresence>
  );
}

export default function App() {
  return (
    <div className="app-shell">
      <ParticleField />
      <CursorGlow />
      <div className="noise" />
      <Navbar />
      <AnimatedRoutes />
    </div>
  );
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import App from './App.jsx';
import './styles.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <BrowserRouter>
      <App />
    </BrowserRouter>
  </React.StrictMode>,
);

:root {
  color-scheme: dark;
  --bg: #050712;
  --panel: rgba(12, 17, 34, 0.72);
  --panel-strong: rgba(15, 24, 48, 0.9);
  --line: rgba(126, 249, 255, 0.18);
  --text: #eef7ff;
  --muted: #9eb4c8;
  --cyan: #6efff0;
  --pink: #ff4fd8;
  --violet: #8d6cff;
  --green: #7cff6b;
  --amber: #ffd166;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
  background:
    radial-gradient(circle at 18% 12%, rgba(255, 79, 216, 0.18), transparent 26rem),
    radial-gradient(circle at 80% 8%, rgba(110, 255, 240, 0.12), transparent 24rem),
    linear-gradient(140deg, #050712 0%, #090d1d 42%, #0b0918 100%);
}

a {
  color: inherit;
  text-decoration: none;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

.app-shell {
  position: relative;
  min-height: 100vh;
  isolation: isolate;
}

.particle-field,
.noise,
.cursor-glow {
  position: fixed;
  inset: 0;
  pointer-events: none;
}

.particle-field {
  z-index: -4;
  opacity: 0.74;
}

.noise {
  z-index: -2;
  opacity: 0.08;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.28) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.2) 1px, transparent 1px);
  background-size: 44px 44px;
  mask-image: linear-gradient(to bottom, black, transparent 85%);
}

.cursor-glow {
  z-index: -1;
  width: 360px;
  height: 360px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(110, 255, 240, 0.16), rgba(255, 79, 216, 0.09) 36%, transparent 70%);
  filter: blur(8px);
  transition: transform 0.08s linear;
}

.nav-frame {
  position: sticky;
  top: 14px;
  z-index: 10;
  width: min(1180px, calc(100% - 32px));
  min-height: 68px;
  margin: 14px auto 0;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 18px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: rgba(5, 9, 22, 0.72);
  backdrop-filter: blur(18px);
  box-shadow: 0 20px 70px rgba(0, 0, 0, 0.32), inset 0 0 22px rgba(110, 255, 240, 0.04);
}

.brand,
.nav-actions,
.nav-links,
.social-row,
.hero-actions,
.profile-links,
.mini-facts {
  display: flex;
  align-items: center;
}

.brand {
  gap: 10px;
  font-weight: 800;
  letter-spacing: 0;
  white-space: nowrap;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 13px;
  background: linear-gradient(135deg, var(--cyan), var(--pink));
  color: #06101a;
  box-shadow: 0 0 28px rgba(110, 255, 240, 0.28);
}

.nav-links {
  justify-content: center;
  gap: 6px;
}

.nav-links a,
.nav-actions a,
.resume-pill,
.primary-button,
.secondary-button,
.profile-links a {
  border: 1px solid transparent;
  transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease, color 0.2s ease;
}

.nav-links a {
  padding: 10px 12px;
  border-radius: 999px;
  color: var(--muted);
  font-size: 0.94rem;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
  border-color: rgba(110, 255, 240, 0.28);
  background: rgba(110, 255, 240, 0.08);
}

.nav-actions {
  justify-content: flex-end;
  gap: 8px;
}

.nav-actions a:not(.resume-pill) {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 13px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
}

.nav-actions a:hover,
.profile-links a:hover,
.secondary-button:hover {
  transform: translateY(-2px);
  border-color: rgba(110, 255, 240, 0.36);
  color: var(--cyan);
}

.resume-pill,
.primary-button,
.secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 42px;
  padding: 0 16px;
  border-radius: 999px;
  font-weight: 800;
}

.resume-pill,
.primary-button {
  background: linear-gradient(135deg, var(--cyan), var(--pink));
  color: #05101a;
  box-shadow: 0 0 30px rgba(110, 255, 240, 0.18);
}

.primary-button:hover {
  transform: translateY(-3px) scale(1.01);
}

.secondary-button,
.profile-links a {
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.055);
  color: var(--text);
}

main {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
}

.page-grid,
.page-section,
.section-block {
  position: relative;
}

.hero-section {
  min-height: calc(100vh - 86px);
  display: grid;
  grid-template-columns: minmax(0, 1.04fr) minmax(320px, 0.72fr);
  align-items: center;
  gap: 44px;
  padding: 76px 0 34px;
}

.hero-copy h1,
.section-heading h1,
.section-heading h2 {
  margin: 0;
  line-height: 1.02;
  letter-spacing: 0;
}

.hero-copy h1 {
  max-width: 820px;
  font-size: clamp(3rem, 7.4vw, 5.9rem);
}

.hero-copy p,
.section-heading p,
.project-card p,
