import { useEffect, useMemo, useState } from 'react';

export default function TypingText({ phrases }) {
  const stablePhrases = useMemo(() => phrases, [phrases]);
  const [phraseIndex, setPhraseIndex] = useState(0);
  const [letterIndex, setLetterIndex] = useState(0);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    const current = stablePhrases[phraseIndex];
    const atEnd = letterIndex === current.length;
    const atStart = letterIndex === 0;
    const delay = deleting ? 34 : atEnd ? 1100 : 58;

    const timer = window.setTimeout(() => {
      if (!deleting && atEnd) {
        setDeleting(true);
        return;
      }
      if (deleting && atStart) {
        setDeleting(false);
        setPhraseIndex((index) => (index + 1) % stablePhrases.length);
        return;
      }
      setLetterIndex((index) => index + (deleting ? -1 : 1));
    }, delay);

    return () => window.clearTimeout(timer);
  }, [deleting, letterIndex, phraseIndex, stablePhrases]);

  return (
    <span className="typing-text">
      {stablePhrases[phraseIndex].slice(0, letterIndex)}
      <span className="typing-caret" />
    </span>
  );
}

import { useEffect, useState } from 'react';

export default function CursorGlow() {
  const [position, setPosition] = useState({ x: -200, y: -200 });

  useEffect(() => {
    const update = (event) => setPosition({ x: event.clientX, y: event.clientY });
    window.addEventListener('pointermove', update);
    return () => window.removeEventListener('pointermove', update);
  }, []);

  return (
    <div
      className="cursor-glow"
      style={{ transform: `translate3d(${position.x - 180}px, ${position.y - 180}px, 0)` }}
    />
  );
}

import { useEffect, useRef } from 'react';

export default function ParticleField() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    let width = 0;
    let height = 0;
    let raf = 0;
    let particles = [];

    const resize = () => {
      width = canvas.width = window.innerWidth * window.devicePixelRatio;
      height = canvas.height = window.innerHeight * window.devicePixelRatio;
      canvas.style.width = `${window.innerWidth}px`;
      canvas.style.height = `${window.innerHeight}px`;
      const count = Math.min(110, Math.floor(window.innerWidth / 13));
      particles = Array.from({ length: count }, () => ({
        x: Math.random() * width,
        y: Math.random() * height,
        vx: (Math.random() - 0.5) * 0.42 * window.devicePixelRatio,
        vy: (Math.random() - 0.5) * 0.42 * window.devicePixelRatio,
        r: (Math.random() * 1.9 + 0.7) * window.devicePixelRatio,
      }));
    };

    const draw = () => {
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = 'rgba(110, 255, 240, 0.76)';
      ctx.strokeStyle = 'rgba(140, 97, 255, 0.18)';
      ctx.lineWidth = window.devicePixelRatio;

      particles.forEach((particle, index) => {
        particle.x += particle.vx;
        particle.y += particle.vy;
        if (particle.x < 0 || particle.x > width) particle.vx *= -1;
        if (particle.y < 0 || particle.y > height) particle.vy *= -1;

        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.r, 0, Math.PI * 2);
        ctx.fill();

        for (let otherIndex = index + 1; otherIndex < particles.length; otherIndex += 1) {
          const other = particles[otherIndex];
          const distance = Math.hypot(particle.x - other.x, particle.y - other.y);
          if (distance < 145 * window.devicePixelRatio) {
            ctx.globalAlpha = 1 - distance / (145 * window.devicePixelRatio);
            ctx.beginPath();
            ctx.moveTo(particle.x, particle.y);
            ctx.lineTo(other.x, other.y);
            ctx.stroke();
            ctx.globalAlpha = 1;
          }
        }
      });

      raf = window.requestAnimationFrame(draw);
    };

    resize();
    draw();
    window.addEventListener('resize', resize);
    return () => {
      window.cancelAnimationFrame(raf);
      window.removeEventListener('resize', resize);
    };
  }, []);

  return <canvas ref={canvasRef} className="particle-field" aria-hidden="true" />;
}

