          or product work around applied AI.
        </p>
      </div>

      <div className="contact-grid">
        {contacts.map(({ label, value, href, icon: Icon }) => (
          <a className="contact-card interactive-card" key={label} href={href} target={label === 'Email' ? undefined : '_blank'} rel="noreferrer">
            <Icon size={24} />
            <span>{label}</span>
            <strong>{value}</strong>
            <ExternalLink size={17} />
          </a>
        ))}
      </div>
    </section>
  );
}
